inline bool evaluate(double score, double *output)
{
  if (output == nullptr || !std::isfinite(score) || score <= left || score >= right) return false;
  const double position = (score - left) / step;
  int index = static_cast<int>(position);
  if (score < left + index * step) --index;
  else if (score >= left + (index + 1) * step) ++index;
  if (index < 0 || index >= cells) return false;
  const double u = (score - (left + index * step)) / step;
  if (!(u >= 0 && u <= 1)) return false;
  double value = coefficient[index][5];
  for (int i = 4; i >= 0; --i) value = value * u + coefficient[index][i];
  if (!std::isfinite(value) || !(value > 0 && value < 1)) return false;
  *output = value;
  return true;
}
